# The elevated right hand currently obscures the departing reference can.
# I will move inward to a known reachable waiting pose and observe the next conveyor objects.
obs, used, result = servo_ee('right', [0.20, 0.0, 1.03, 0.5, -0.5, 0.5, 0.5], 1.0, 15)
print('stage', used, result, obs['state']['right_ee_pose'])
hold = {k: v for k, v in obs['state'].items() if k.endswith('joint_state')}
for i in range(60):
    obs, reward, terminated, truncated, info = step(hold)
    if terminated or truncated:
        break
print('waited', i+1, 'state', obs['state']['right_ee_pose'])

